// ---- SID engine (lib/sid: 3-voice 6581-style core, ADSR, filter) --------------------------------
#include "sid.h"
static sid_t sid;
static uint8_t sidWaveBits(int w) {
  switch (w) { case 1: return SID_CTRL_SAWTOOTH; case 2: return SID_CTRL_PULSE; case 3: return SID_CTRL_NOISE; default: return SID_CTRL_TRIANGLE; }
}
static void sidSetup() {
  sid_init(&sid, 44100, SID_CLOCK_PAL_HZ);
  for (int v = 0; v < 3; v++) {
    sid_set_adsr(&sid, v, 0, 8, 9, 5);          // fast attack, 300 ms decay to sustain 9/15, ~170 ms release
    sid_set_pulse_width(&sid, v, sidVoices[v].pulseWidth / 100.0f);
    sid_set_control(&sid, v, sidWaveBits(sidVoices[v].waveform));
  }
  sid_set_volume(&sid, 15);
}
void gateVoice(int v, float freq, int durationMs) {
  if (v < 0 || v > 2) return;
  sidVoices[v].freq = freq;
  sidVoices[v].gated = true;
  sidVoices[v].stage = 1;
  sidVoices[v].remaining = (long)44100 * durationMs / 1000;
  lastVoice = v;
  // SID: program the oscillator and open the gate (envelope attack starts)
  sid_set_freq_hz(&sid, v, freq);
  sid_set_pulse_width(&sid, v, sidVoices[v].pulseWidth / 100.0f);
  sid_set_control(&sid, v, sidWaveBits(sidVoices[v].waveform) | SID_CTRL_GATE);
}
void renderVoices() {
  // SID: render until every gate is closed and every envelope has died out (max 3 s)
  int16_t buf[256];
  long guard = (long)44100 * 3;
  while (guard > 0) {
    bool active = false;
    for (int v = 0; v < 3; v++) {
      SidVoice &sv = sidVoices[v];
      if (sv.gated) {
        sv.remaining -= 256;
        if (sv.remaining <= 0) { sv.gated = false; sv.stage = 4; sid_gate(&sid, v, false); }
        active = true;
      } else if (sid.voice[v].envelope != 0) { active = true; } else { sv.stage = 0; }
    }
    if (!active) break;
    sid_render(&sid, buf, 256);
    for (int i = 0; i < 256; i++) buf[i] = (int16_t)(buf[i] / 2);   // headroom; Speaker::writeSamples applies the volume
    speaker_1.writeSamples(buf, 256);
    guard -= 256;
  }
}
void playPulseNote(float freq, int durationMs) {
  gateVoice(0, freq, durationMs);
  renderVoices();
}
void playCurrentNote() {
  int base = NOTE_TABLE[noteIndex];
  int octShift = octave - 4;
  float freq = base * pow(2.0f, octShift);
  if (freq < 80) freq = 80;
  if (freq > 1500) freq = 1500;
  gateVoice(0, freq, 300);
  renderVoices();
}
