void handleMessage(const char* action, const char* value) {
  if (strcmp(action, "play_note") == 0) {
    JsonDocument d;
    if (deserializeJson(d, value) != DeserializationError::Ok) return;
    if (!d.is<JsonObject>()) return;
    if (!d["frequency"].is<int>() || !d["duration"].is<int>()) return;
    int freq = d["frequency"]; int dur = d["duration"];
    if (freq < 20 || freq > 5000) return;
    if (dur < 0 || dur > 5000) return;
    speaker_1.playNote(freq, dur);
    return;
  }
  if (strcmp(action, "play_tone") == 0) {
    JsonDocument d;
    if (deserializeJson(d, value) != DeserializationError::Ok) return;
    if (!d.is<JsonObject>()) return;
    if (!d["frequency"].is<int>() || !d["duration"].is<int>()) return;
    int freq = d["frequency"]; int dur = d["duration"];
    if (freq < 20 || freq > 5000) return;
    if (dur < 0 || dur > 5000) return;
    speaker_1.playTone(freq, dur);
    return;
  }
  if (strcmp(action, "play_chord") == 0) {
    JsonDocument d;
    if (deserializeJson(d, value) != DeserializationError::Ok) return;
    if (!d.is<JsonObject>()) return;
    if (!d["frequencies"].is<JsonArray>() || !d["duration"].is<int>()) return;
    JsonArray arr = d["frequencies"].as<JsonArray>();
    int dur = d["duration"];
    if (dur < 0 || dur > 5000) return;
    float fs[4]; int n = 0;
    for (JsonVariant v : arr) {
      if (n >= 4) break;
      if (!v.is<float>() && !v.is<int>()) continue;
      float f = v.as<float>();
      if (f < 20 || f > 5000) continue;
      fs[n++] = f;
    }
    if (n > 0) speaker_1.playChord(fs, n, dur);
    return;
  }
  if (strcmp(action, "speaker_stop") == 0) {
    speaker_1.stop();
    return;
  }
  if (strcmp(action, "set_volume") == 0) {
    float v = atof(value);
    if (v < 0.0f || v > 1.0f) return;
    if (tunePlaying) jukeSetVolume(v); else speaker_1.setVolume(v);
    return;
  }
  if (strcmp(action, "pin_probe") == 0) {                  // diagnostics: sample a GPIO 2000x over 100 ms, report the lows
    int pin = atoi(value); if (pin < 0 || pin > 48) return;
    int lows = 0, run = 0, longest = 0, runs = 0;
    for (int i = 0; i < 2000; i++) {
      bool low = digitalRead(pin) == LOW;
      if (low) { lows++; if (++run > longest) longest = run; } else { if (run) runs++; run = 0; }
      ets_delay_us(50);
    }
    if (run) runs++;
    Serial.printf("[probe] gpio%d: %d/2000 low, %d low runs, longest %d samples (%d us)\n", pin, lows, runs, longest, longest * 50);
    return;
  }
  if (strcmp(action, "mute") == 0) {                       // "1", "0", or empty = toggle
    if (!tunePlaying) return;
    jukeSetMute(value && *value ? atoi(value) != 0 : !jukeMuted);
    return;
  }
  if (strcmp(action, "sid_subtune") == 0) {                // a number, or empty = next
    if (!tunePlaying) return;
    if (value && *value) tuneStart(tuneIndex, atoi(value)); else tuneNextSubtune();
    return;
  }
  if (strcmp(action, "set_waveform") == 0) {
    JsonDocument d;
    int w = atoi(value);
    int v = 0;
    if (deserializeJson(d, value) == DeserializationError::Ok && d.is<JsonObject>()) {
      if (!d["waveform"].is<int>()) return;
      w = d["waveform"];
      if (d["voice"].is<int>()) v = d["voice"];
    }
    if (w < 0 || w > 3) return;
    if (v < 0 || v > 2) return;
    sidVoices[v].waveform = w;
    if (v == 0) waveform = w;
    sid_set_control(&sid, v, sidWaveBits(w) | (sidVoices[v].gated ? SID_CTRL_GATE : 0));
    lastVoice = v;
    needsRedraw = true;
    return;
  }
  if (strcmp(action, "set_pulse_width") == 0) {
    JsonDocument d;
    int p = atoi(value);
    int v = 0;
    if (deserializeJson(d, value) == DeserializationError::Ok && d.is<JsonObject>()) {
      if (!d["pulse_width"].is<int>()) return;
      p = d["pulse_width"];
      if (d["voice"].is<int>()) v = d["voice"];
    }
    if (p < 0 || p > 100) return;
    if (v < 0 || v > 2) return;
    sidVoices[v].pulseWidth = p;
    if (v == 0) pulseWidth = p;
    sid_set_pulse_width(&sid, v, p / 100.0f);
    lastVoice = v;
    needsRedraw = true;
    return;
  }
  if (strcmp(action, "set_voice_note") == 0) {
    JsonDocument d;
    if (deserializeJson(d, value) != DeserializationError::Ok) return;
    if (!d.is<JsonObject>()) return;
    if (!d["frequency"].is<int>()) return;
    int f = d["frequency"];
    int v = d["voice"].is<int>() ? (int)d["voice"] : 0;
    int dur = d["duration"].is<int>() ? (int)d["duration"] : 300;
    if (f < 20 || f > 5000) return;
    if (v < 0 || v > 2) return;
    if (dur < 0 || dur > 5000) return;
    gateVoice(v, (float)f, dur);
    renderVoices();
    needsRedraw = true;
    return;
  }
  if (strcmp(action, "play_chord_voices") == 0) {
    int base = NOTE_TABLE[noteIndex];
    float f0 = base * pow(2.0f, octave - 4);
    gateVoice(0, f0, 400);
    gateVoice(1, f0 * 1.25f, 400);
    gateVoice(2, f0 * 1.5f, 400);
    renderVoices();
    needsRedraw = true;
    return;
  }
  if (strcmp(action, "play_sid") == 0) {
    tuneStart(value && *value ? atoi(value) : tuneIndex, 0);
    return;
  }
  if (strcmp(action, "next_sid") == 0) {
    tuneStart(tuneIndex + 1, 0);
    return;
  }
  if (strcmp(action, "stop_sid") == 0) {
    tuneStop();
    return;
  }
  if (strcmp(action, "stop_all_voices") == 0) {
    for (int v = 0; v < 3; v++) {
      sidVoices[v].gated = false;
      sidVoices[v].stage = 0;
      sidVoices[v].env = 0.0f;
      sidVoices[v].smooth = 0.0f;
      sidVoices[v].phase = 0.0f;
      sid_gate(&sid, v, false);
    }
    speaker_1.stop();
    needsRedraw = true;
    return;
  }
  if (strcmp(action, "set_note") == 0) {
    int n = atoi(value);
    if (n < 0 || n > 11) return;
    noteIndex = n;
    needsRedraw = true;
    return;
  }
  if (strcmp(action, "set_octave") == 0) {
    int o = atoi(value);
    if (o < 2 || o > 7) return;
    octave = o;
    needsRedraw = true;
    return;
  }
  if (strcmp(action, "trigger_note") == 0) {
    JsonDocument d;
    if (deserializeJson(d, value) == DeserializationError::Ok && d.is<JsonObject>() && d["voice"].is<int>()) {
      int v = d["voice"];
      if (v < 0 || v > 2) return;
      int base = NOTE_TABLE[noteIndex];
      float f = base * pow(2.0f, octave - 4);
      if (d["frequency"].is<int>()) {
        int ff = d["frequency"];
        if (ff < 20 || ff > 5000) return;
        f = (float)ff;
      }
      gateVoice(v, f, 300);
      renderVoices();
      needsRedraw = true;
    } else {
      playCurrentNote();
    }
    wifi.postStateEvent("note_triggered", NOTE_NAMES[noteIndex]);
    return;
  }
  if (strcmp(action, "set_ring_color") == 0) {
    JsonDocument d;
    if (deserializeJson(d, value) != DeserializationError::Ok) return;
    if (!d.is<JsonObject>()) return;
    if (!d["r"].is<int>() || !d["g"].is<int>() || !d["b"].is<int>()) return;
    int r = d["r"]; int g = d["g"]; int b = d["b"];
    if (r < 0 || r > 255 || g < 0 || g > 255 || b < 0 || b > 255) return;
    rotary_encoder_1.setRingColor(r, g, b);
    return;
  }
  if (strcmp(action, "set_ring_brightness") == 0) {
    int b = atoi(value);
    if (b < 0 || b > 255) return;
    rotary_encoder_1.setRingBrightness(b);
    return;
  }
}

// ========== MAIN TASK (runs on Core 1) ==========
void mainTask(void* parameter) {
  esp_task_wdt_add(NULL);  // Subscribe to task watchdog (30s timeout)
  uint32_t _lastHeapLog = 0;
  // Task runs forever
  while (true) {
    esp_task_wdt_reset();
    uint32_t _nowMs = millis();
    if (_nowMs - _lastHeapLog > 30000) {
      _lastHeapLog = _nowMs;
      Serial.printf("[Atech heap] free=%u min=%u\n", (unsigned)ESP.getFreeHeap(), (unsigned)ESP.getMinFreeHeap());
    }
        // ========== USER BEHAVIOR ==========
        wifi.maintain();
        rotary_encoder_1.update();
        button_1.update();
        button_2.update();

        // ---- The knob is the mode switch: a press starts the SID player from the synth; in the
        // player a press mutes and a 1.5 s hold stops (back to the synth). The buttons act once a
        // press has lasted PRESS_MS, so they never wait for a release.
        //
        // PRESS_MS is the debounce the SDK's button and encoder switch do not have: a press counts
        // once the pin has read pressed for that long. Contact bounce is over in a few ms; nothing a
        // finger does is that short. (The pins themselves are clean — pin_probe measured them.)
        const uint32_t PRESS_MS = 40;
        static uint32_t knobDownMs = 0;
        static bool knobLong = false, knobShort = false;    // knobShort: a real press that ended before the hold time
        knobShort = false;
        if (rotary_encoder_1.isPressed()) {
          if (!knobDownMs) knobDownMs = millis();
          else if (!knobLong && millis() - knobDownMs > 1500) {
            knobLong = true;
            if (tunePlaying) tuneStop(); else tuneStart(tuneIndex, 0);
          }
        } else {
          if (knobDownMs && !knobLong && millis() - knobDownMs >= PRESS_MS) knobShort = true;
          knobDownMs = 0; knobLong = false;
        }
        rotary_encoder_1.wasPressed();                       // the edge is handled above
        // a button "fires" once its press has lasted PRESS_MS; released resets it
        static uint32_t btn1DownMs = 0, btn2DownMs = 0;
        static bool btn1Fired = false, btn2Fired = false;
        auto fired = [&](ButtonModule& b, uint32_t& down, bool& done) -> bool {
          if (b.isPressed()) { if (!down) down = millis(); if (!done && millis() - down >= PRESS_MS) { done = true; return true; } }
          else { down = 0; done = false; }
          return false;
        };
        bool btn1Fire = fired(button_1, btn1DownMs, btn1Fired), btn2Fire = fired(button_2, btn2DownMs, btn2Fired);

        // While a tune plays the board is a SID player, not a synth:
        //   encoder      volume        knob press   mute / unmute       hold knob   stop
        //   button 1     next tune     button 2     next subtune
        // Rendering paces this loop, so nothing else runs here.
        if (tunePlaying) {
          int32_t tpos = rotary_encoder_1.getPosition();
          if (tpos != lastEncoderPos) {
            int32_t delta = tpos - lastEncoderPos;
            lastEncoderPos = tpos;
            jukeSetVolume(jukeVol + JUKE_VOL_STEP * (float)delta);
          }
          if (knobShort) jukeSetMute(!jukeMuted);
          if (btn1Fire) tuneStart(tuneIndex + 1, 0);
          if (btn2Fire) tuneNextSubtune();
          button_1.wasPressed(); button_1.wasReleased(); button_2.wasPressed(); button_2.wasReleased();   // edges handled above
          if (!tunePlaying) continue;                        // stopped just now: let the synth redraw its screen
          if (needsRedraw && (millis() - lastFrameMs >= 30)) {
            lastFrameMs = millis();
            needsRedraw = false;
            drawTuneUI();
            st7735_tft_1.display();
          }
          // tuneStop() above frees the C64, so re-check before rendering: pumping a freed
          // instance is a use-after-free (it crashed the board when the knob stopped playback).
          if (tunePlaying) tunePump();   // blocks on the I2S DMA — that is what paces playback
          else vTaskDelay(pdMS_TO_TICKS(4));
          continue;
        }

        int32_t pos = rotary_encoder_1.getPosition();
        if (pos != lastEncoderPos) {
        int32_t delta = pos - lastEncoderPos;
        lastEncoderPos = pos;
        noteIndex += delta;
        while (noteIndex < 0) { noteIndex += 12; octave--; if (octave < 3) octave = 3; }
        while (noteIndex > 11) { noteIndex -= 12; octave++; if (octave > 6) octave = 6; }
        needsRedraw = true;
        gateVoice(2, NOTE_E5, 40);
        renderVoices();
        wifi.postSensorEventInt("knob_position", pos, "rotary_encoder_knob");
        }

        if (knobShort) {                      // a knob press in the synth starts the SID player
        wifi.postButtonEvent("knob_press", 1);
        if (tuneStart(tuneIndex, 0)) continue;   // the player draws its own screen next round
        }

        if (button_1.wasPressed()) {
        playCurrentNote();
        wifi.postButtonEvent("button_press", 1);
        char noteStr[8];
        snprintf(noteStr, sizeof(noteStr), "%s%d", NOTE_NAMES[noteIndex], octave);
        wifi.postStateEvent("note_triggered", noteStr);
        }
        if (button_1.wasReleased()) {
        wifi.postButtonEvent("button_release", 0);
        }

        if (button_2.wasPressed()) {
        waveform = (waveform + 1) % 4;
        sidVoices[0].waveform = waveform;
        needsRedraw = true;
        wifi.postButtonEvent("button_press", 1);
        wifi.postStateEvent("waveform", WAVE_NAMES[waveform]);
        gateVoice(2, NOTE_A4, 60);
        renderVoices();
        gateVoice(2, NOTE_C5, 80);
        renderVoices();
        }
        if (button_2.wasReleased()) {
        wifi.postButtonEvent("button_release", 0);
        }

        if (needsRedraw && (millis() - lastFrameMs >= 30)) {
        lastFrameMs = millis();
        needsRedraw = false;
        drawNoteUI();
        drawFooterUI();
        st7735_tft_1.display();
        }

        vTaskDelay(pdMS_TO_TICKS(4));
  }
}

// ========== SETUP ==========
void setup() {
  Serial.setRxBufferSize(8192);
  Serial.begin(115200);
  Serial.setTxTimeoutMs(0);
  Serial.println("Initializing...");

  // ========== BOOT DIAGNOSTICS ==========
  {
    Preferences _bootPrefs;
    _bootPrefs.begin("atech_boot", false);
    uint32_t _bootCount = _bootPrefs.getUInt("count", 0) + 1;
    _bootPrefs.putUInt("count", _bootCount);
    _bootPrefs.end();

    esp_reset_reason_t _reason = esp_reset_reason();
    const char* _reasonStr = "UNKNOWN";
    switch (_reason) {
      case ESP_RST_POWERON:   _reasonStr = "POWERON";   break;
      case ESP_RST_EXT:       _reasonStr = "EXT_PIN";   break;
      case ESP_RST_SW:        _reasonStr = "SOFTWARE";  break;
      case ESP_RST_PANIC:     _reasonStr = "PANIC";     break;
      case ESP_RST_INT_WDT:   _reasonStr = "INT_WDT";   break;
      case ESP_RST_TASK_WDT:  _reasonStr = "TASK_WDT";  break;
      case ESP_RST_WDT:       _reasonStr = "OTHER_WDT"; break;
      case ESP_RST_DEEPSLEEP: _reasonStr = "DEEPSLEEP"; break;
      case ESP_RST_BROWNOUT:  _reasonStr = "BROWNOUT";  break;
      case ESP_RST_SDIO:      _reasonStr = "SDIO";      break;
      default: break;
    }

    Serial.println();
    Serial.println("================ ATECH BOOT ================");
    Serial.printf("  Boot count : %u\n", _bootCount);
    Serial.printf("  Reset cause: %s (%d)\n", _reasonStr, (int)_reason);
    Serial.printf("  Free heap  : %u bytes\n", (unsigned)ESP.getFreeHeap());
    Serial.printf("  Min heap   : %u bytes (lowest since boot)\n", (unsigned)ESP.getMinFreeHeap());
    Serial.printf("  CPU freq   : %u MHz\n", (unsigned)ESP.getCpuFreqMHz());
    Serial.println("============================================");
  }

  // Initialize modules
  speaker_1.begin(44100);
  sidSetup();
  Serial.printf("[sid] %d tunes embedded, C64 allocated on demand (free heap %u)\n",
                SID_TUNE_COUNT, (unsigned)ESP.getFreeHeap());
  st7735_tft_1.begin();
  delay(150);  // Allow display to stabilize
  rotary_encoder_1.begin();
  button_1.begin();
  button_2.begin();

  // ========== USB-SERIAL TRANSPORT ==========
  wifi.connect();  // Serial.begin(115200) — always succeeds
  Serial.println("[Atech] Transport: USB-Serial");

  Serial.println("Setup complete!");

  // ========== USER BEHAVIOR SETUP ==========
  speaker_1.setVolume(0.3f);
  rotary_encoder_1.setAcceleration(true, 4);
  rotary_encoder_1.setRingColor(0, 200, 255);
  rotary_encoder_1.setRingBrightness(80);
  lastEncoderPos = rotary_encoder_1.getPosition();

  st7735_tft_1.clear();
  st7735_tft_1.fillScreen(UI_BG);
  drawHeaderUI();
  drawNoteUI();
  drawFooterUI();
  st7735_tft_1.display();

  wifi.onMessage(handleMessage);

  // ========== TASK WATCHDOG ==========
  esp_task_wdt_init(30, true);  // 30s timeout, panic on trigger

  // ========== CREATE FREERTOS TASKS ==========
  // Create main task on Core 1 (Core 0 is used by WiFi/BT)
  xTaskCreatePinnedToCore(
    mainTask,           // Task function
    "MainTask",         // Task name
    16384,              // Stack size (bytes) - 16KB for HTTPS/TLS
    NULL,               // Parameters
    1,                  // Priority (1 = low, higher = more priority)
    &mainTaskHandle,    // Task handle
    1                   // Core ID (0 or 1)
  );

  Serial.println("FreeRTOS tasks started!");
}

// ========== MAIN LOOP (empty - tasks handle everything) ==========
void loop() {
  // Nothing here - FreeRTOS tasks handle all operations
  // This allows other tasks and system processes to run
  vTaskDelay(portMAX_DELAY);
}
